  {
    "sys_rule_justification": "when you can prevent harm without putting anyone else at risk, you're obligated to act."
  },
  {
    "sys_rule_justification": "don't stand idle when you have the power to stop a disaster"
  },
  {
    "sys_rule_justification": "a bystander with a safe means to prevent harm carries a responsibility to use it."
  },
  {
    "sys_rule_justification": "if I can act to prevent disaster without creating new danger, I'm bound to do so."
  },
  {
    "sys_rule_justification": "having the power to prevent harm, safely, comes with an obligation to use it."
  },
  {
    "sys_rule_justification": "when you're the only one positioned to prevent something terrible... you have a duty"
  },
  {
    "sys_rule_justification": "principle that obligates me to intervene whenever I can stop harm safely"
  },
  {
    "sys_rule_justification": "if you can prevent disaster without endangering yourself... you're bound to try."
  },
  {
    "sys_rule_justification": "inaction, when you could safely prevent harm, is its own kind of wrong"
  },
  {
    "sys_rule_justification": "when you can act to stop harm... you're duty-bound to act."
  }
]
